template:
% 参数由系统自动注入：\def\radius{3} \def\anglea{40} \def\showchord{1} \def\showdiameter{1} \def\showperp{1} \def\showmidpoint{1}
% 视觉归一化：把圆直径缩放到 6（单位由 coordScale 决定）。
% 弦 AB 水平对称放置：A(-x,y)、B(x,y)，直径 CD 垂直、过弦中点 M。
\pgfmathsetmacro{\figscale}{3 / \radius}
\pgfmathsetmacro{\chordx}{\radius*cos(\anglea)}
\pgfmathsetmacro{\chordy}{\radius*sin(\anglea)}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  \coordinate (O) at (0,0);
  \coordinate (A) at (-\chordx,\chordy);
  \coordinate (B) at (\chordx,\chordy);
  \coordinate (M) at (0,\chordy);
  \coordinate (C) at (0,\radius);
  \coordinate (D) at (0,-\radius);
  % 圆
  \draw[thick] (O) circle [radius=\radius];
  % 直径 CD（垂直于弦）
  \ifnum\showdiameter>0
    \draw[thick] (C) -- (D);
  \fi
  % 弦 AB
  \ifnum\showchord>0
    \draw[thick] (A) -- (B);
  \fi
  % 垂线段 OM + 直角记号（OM 与 AB 垂直）
  \ifnum\showperp>0
    \draw[thick] (O) -- (M);
    \pgfmathsetmacro{\rs}{min(0.25, \radius*0.14)}
    \draw[thick] (\rs,\chordy) -- (\rs,{\chordy-\rs}) -- (0,{\chordy-\rs});
  \fi
  % 端点与中点
  \ifnum\showchord>0
    \fill (A) circle [radius=1.6pt];
    \fill (B) circle [radius=1.6pt];
    \node[left=3pt] at (A) {$A$};
    \node[right=3pt] at (B) {$B$};
  \fi
  \ifnum\showdiameter>0
    \fill (C) circle [radius=1.6pt];
    \fill (D) circle [radius=1.6pt];
    \node[above=3pt] at (C) {$C$};
    \node[below=3pt] at (D) {$D$};
  \fi
  \ifnum\showmidpoint>0
    \fill (M) circle [radius=1.6pt];
    \node[below=3pt] at (M) {$M$};
  \fi
  % 圆心 O
  \fill (O) circle [radius=1.6pt];
  \node[below left=3pt] at (O) {$O$};
\end{tikzpicture}
